artifacts.solve_py:
import os, sys, csv, json, math

# ── Read data ──────────────────────────────────────────────────────────────
DATA = '/app/data'
SUB  = '/app/submissions'
os.makedirs(SUB, exist_ok=True)

with open(f'{DATA}/config.json') as f:
    cfg = json.load(f)

bases = []
with open(f'{DATA}/candidate_bases.csv') as f:
    for r in csv.DictReader(f):
        bases.append(r)
zones = []
with open(f'{DATA}/demand_zones.csv') as f:
    for r in csv.DictReader(f):
        zones.append(r)
scenarios = []
with open(f'{DATA}/scenarios.csv') as f:
    for r in csv.DictReader(f):
        scenarios.append(r)
equity = {}
with open(f'{DATA}/equity_requirements.csv') as f:
    for r in csv.DictReader(f):
        equity[r['equity_group']] = r
ground_cap = {}
with open(f'{DATA}/district_ground_capacity.csv') as f:
    for r in csv.DictReader(f):
        ground_cap[(r['scenario_id'], r['district'])] = float(r['max_ground_calls_per_day'])
corridors = {}
with open(f'{DATA}/air_corridor_rules.csv') as f:
    for r in csv.DictReader(f):
        corridors[(r['scenario_id'], r['origin_region'], r['destination_district'])] = r
exceptions = set()
with open(f'{DATA}/base_zone_exceptions.csv') as f:
    for r in csv.DictReader(f):
        if r['allowed'] == '0':
            exceptions.add((r['scenario_id'], r['base_id'], r['zone_id']))
staffing = {}
with open(f'{DATA}/base_region_staffing.csv') as f:
    for r in csv.DictReader(f):
        staffing[r['region']] = (int(r['max_open_bases']), int(r['max_drones']))

# ── Preprocess ─────────────────────────────────────────────────────────────
B = [b['base_id'] for b in bases]
Z = [z['zone_id'] for z in zones]
S = [s['scenario_id'] for s in scenarios]

base_info = {b['base_id']: b for b in bases}
zone_info = {z['zone_id']: z for z in zones}
scen_info = {s['scenario_id']: s for s in scenarios}

def dist(bid, zid):
    bx, by = float(base_info[bid]['x_km']), float(base_info[bid]['y_km'])
    zx, zy = float(zone_info[zid]['x_km']), float(zone_info[zid]['y_km'])
    return math.hypot(bx - zx, by - zy)

# Corridor lookup: for scenario s, region o, district d
def get_corridor(s, o, d):
    if (s, o, d) in corridors:
        return corridors[(s, o, d)]
    if ('ALL', o, d) in corridors:
        return corridors[('ALL', o, d)]
    return None

# Eligibility: drone base b can serve zone z in scenario s
def eligible(s, b, z):
    if (s, b, z) in exceptions:
        return False
    if ('ALL', b, z) in exceptions:
        return False
    if dist(b, z) > float(base_info[b]['range_km']):
        return False
    cor = get_corridor(s, base_info[b]['region'], zone_info[z]['district'])
    if cor is not None:
        if int(cor['requires_weather_hardened']) == 1 and int(base_info[b]['weather_hardened']) == 0:
            return False
    return True

# Response time components
def drone_time(s, b, z):
    """Base response time (without queue wait) in minutes."""
    si = scen_info[s]
    bi = base_info[b]
    d = dist(b, z)
    speed = float(cfg['base_drone_speed_kmph']) * float(si['drone_speed_multiplier'])
    travel = d / speed * 60.0
    launch = float(bi['launch_delay_min'])
    service = float(cfg['service_minutes_at_scene'])
    cor = get_corridor(s, bi['region'], zone_info[z]['district'])
    extra = float(cor['extra_minutes']) if cor else 0.0
    return launch + travel + service + extra

def ground_time(s, z):
    si = scen_info[s]
    return float(zone_info[z]['baseline_ems_min']) * float(si['ground_time_multiplier'])

# Precompute eligibility and times
elig = {}
dtime = {}
gtime = {}
for s in S:
    for z in Z:
        gtime[(s, z)] = ground_time(s, z)
        for b in B:
            if eligible(s, b, z):
                elig[(s, z, b)] = True
                dtime[(s, z, b)] = drone_time(s, b, z)
            else:
                elig[(s, z, b)] = False

# Calls per scenario-zone
calls = {}
for s in S:
    m = float(scen_info[s]['call_multiplier'])
    for z in Z:
        calls[(s, z)] = float(zone_info[z]['base_calls_per_day']) * m

# Total calls per scenario
tot_calls_s = {s: sum(calls[(s, z)] for z in Z) for s in S}
tot_calls = sum(tot_calls_s[s] for s in S)

# Tail scenarios: two most severe (highest weather_severity, then probability)
tail_scens = sorted(S, key=lambda s: (-int(scen_info[s]['weather_severity']), float(scen_info[s]['probability'])))[:2]

# Equity targets
eq_target = {g: float(equity[g]['response_target_min']) for g in equity}
eq_min_fast = {g: float(equity[g]['min_fast_share']) for g in equity}
eq_tail_min_fast = {g: float(equity[g]['tail_min_fast_share']) for g in equity}

# Kit reserve: max over scenarios
kit_reserve_max = max(float(scen_info[s]['kit_reserve_factor']) for s in S)

# Queue: service capacity per drone per day
# A drone can serve: daily_service_hours*60 / (service + reload) calls per day
cap_per_drone = float(cfg['daily_service_hours']) * 60.0 / (float(cfg['service_minutes_at_scene']) + float(cfg['reload_minutes']))
max_util = float(cfg['max_queue_utilization'])

# ── Build MIP ──────────────────────────────────────────────────────────────
from pyscipopt import Model, quicksum

model = Model('naloxone_drone')
model.setParam("gaprel", 0.0005)

time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        time_limit = min(time_limit, float(env_limit))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

# Variables
y = {}  # base open
d = {}  # drones staged
k = {}  # kits staged
for b in B:
    y[b] = model.addVar(name=f"y_{b}", vtype='B', lb=0, ub=1, obj=0.0)
    d[b] = model.addVar(name=f"d_{b}", vtype='I', lb=0, ub=int(base_info[b]['max_drones']), obj=0.0)
    k[b] = model.addVar(name=f"k_{b}", vtype='I', lb=0, ub=int(base_info[b]['kit_capacity']), obj=0.0)

x = {}  # x[s,z,b] drone dispatch
g = {}  # g[s,z] ground dispatch
for s in S:
    for z in Z:
        g[(s, z)] = model.addVar(name=f"g_{s}_{z}", vtype='B', lb=0, ub=1, obj=0.0)
        for b in B:
            if (s, z, b) in elig:
                x[(s, z, b)] = model.addVar(name=f"x_{s}_{z}_{b}", vtype='B', lb=0, ub=1, obj=0.0)

# Fast service indicator f[s,z]
fast = {}
for s in S:
    for z in Z:
        fast[(s, z)] = model.addVar(name=f"fast_{s}_{z}", vtype='B', lb=0, ub=1, obj=0.0)

# Backup variables for high-priority zones
bkp = {}
hp_zones = [z for z in Z if int(zone_info[z]['priority_zone']) == 1]
for s in S:
    for z in hp_zones:
        for b in B:
            if (s, z, b) in elig:
                for b2 in B:
                    if b2 != b and (s, z, b2) in elig:
                        bkp[(s, z, b, b2)] = model.addVar(name=f"bkp_{s}_{z}_{b}_{b2}", vtype='B', lb=0, ub=1, obj=0.0)

# Priority variables: p1, p2, p3 (exactly one = 1)
p1 = {}
p2 = {}
p3 = {}
for s in S:
    for z in Z:
        p1[(s, z)] = model.addVar(name=f"p1_{s}_{z}", vtype='B', lb=0, ub=1, obj=0.0)
        p2[(s, z)] = model.addVar(name=f"p2_{s}_{z}", vtype='B', lb=0, ub=1, obj=0.0)
        p3[(s, z)] = model.addVar(name=f"p3_{s}_{z}", vtype='B', lb=0, ub=1, obj=0.0)

# ── Constraints ────────────────────────────────────────────────────────────

# 1. Exactly one dispatch per scenario-zone
for s in S:
    for z in Z:
        lhs = g[(s, z)]
        for b in B:
            if (s, z, b) in x:
                lhs += x[(s, z, b)]
        model.addCons(lhs == 1, name=f"dispatch_{s}_{z}")

# 2. Drone only if base open
for (s, z, b), var in x.items():
    model.addCons(var <= y[b], name=f"open_{s}_{z}_{b}")

# 3. Corridor capacity
regions = ['north', 'central', 'east', 'south', 'west']
for s in S:
    for o in regions:
        for dd in regions:
            cor = get_corridor(s, o, dd)
            if cor is None:
                continue
            cap = float(cor['max_calls_per_day'])
            lhs = 0
            for b in B:
                if base_info[b]['region'] != o:
                    continue
                for z in Z:
                    if zone_info[z]['district'] != dd:
                        continue
                    if (s, z, b) in x:
                        lhs += calls[(s, z)] * x[(s, z, b)]
            if lhs != 0:
                model.addCons(lhs <= cap, name=f"corridor_{s}_{o}_{dd}")

# 4. Ground district capacity
for s in S:
    for dd in regions:
        cap = ground_cap.get((s, dd), 0.0)
        lhs = sum(calls[(s, z)] * g[(s, z)] for z in Z if zone_info[z]['district'] == dd)
        if lhs != 0:
            model.addCons(lhs <= cap, name=f"ground_{s}_{dd}")

# 5. Total ground share in flyable scenarios
flyable = [s for s in S if int(scen_info[s]['no_fly']) == 0]
if flyable:
    total_flyable = sum(tot_calls_s[s] for s in flyable)
    lhs = sum(calls[(s, z)] * g[(s, z)] for s in flyable for z in Z)
    model.addCons(lhs <= float(cfg['max_ground_share_flyable']) * total_flyable, name="ground_share")

# 6. High-priority backup
for s in S:
    for z in hp_zones:
        for b in B:
            if (s, z, b) not in x:
                continue
            # sum of backup indicators >= x[s,z,b]
            lhs = 0
            for b2 in B:
                if b2 != b and (s, z, b2) in elig and (s, z, b2) in x:
                    lhs += bkp[(s, z, b, b2)]
            model.addCons(lhs >= x[(s, z, b)], name=f"backup_{s}_{z}_{b}")
            # backup base must be open
            for b2 in B:
                if b2 != b and (s, z, b2) in elig and (s, z, b2) in x:
                    model.addCons(bkp[(s, z, b, b2)] <= y[b2], name=f"bkp_open_{s}_{z}_{b}_{b2}")

# 7. Queue utilization
for s in S:
    for b in B:
        # load = sum of calls assigned to base b in scenario s
        load = sum(calls[(s, z)] * x[(s, z, b)] for z in Z if (s, z, b) in x)
        # load <= max_util * cap_per_drone * drones
        model.addCons(load <= max_util * cap_per_drone * d[b], name=f"queue_{s}_{b}")

# 8. Kit coverage
for b in B:
    for s in S:
        reserve = float(scen_info[s]['kit_reserve_factor'])
        load = sum(calls[(s, z)] * x[(s, z, b)] for z in Z if (s, z, b) in x)
        model.addCons(reserve * load <= k[b], name=f"kits_{s}_{b}")

# 9. Budget
fixed_cost = sum(float(base_info[b]['fixed_cost']) * y[b] for b in B)
drone_cost = float(cfg['drone_weekly_cost']) * sum(d[b] for b in B)
kit_cost = float(cfg['kit_unit_cost']) * sum(k[b] for b in B)
model.addCons(fixed_cost + drone_cost + kit_cost <= float(cfg['weekly_budget']), name="budget")

# 10. Fleet
model.addCons(sum(d[b] for b in B) <= int(cfg['total_drones_available']), name="fleet")

# 11. Open base count
model.addCons(sum(y[b] for b in B) <= int(cfg['max_open_bases']), name="max_open")
model.addCons(sum(y[b] for b in B) >= int(cfg['min_open_bases']), name="min_open")

# 12. Staffing
for reg, (max_ob, max_dr) in staffing.items():
    reg_bases = [b for b in B if base_info[b]['region'] == reg]
    if reg_bases:
        model.addCons(sum(y[b] for b in reg_bases) <= max_ob, name=f"staff_ob_{reg}")
        model.addCons(sum(d[b] for b in reg_bases) <= max_dr, name=f"staff_dr_{reg}")

# 13. Equity fast-share
# For each group g: demand-weighted share of calls with response <= target >= min_fast_share
# "fast" means: drone response time <= target OR ground time <= target
for s in S:
    for z in Z:
        grp = zone_info[z]['equity_group']
        tgt = eq_target[grp]
        # fast[s,z] <= (1 if gt<=tgt else 0)*g[s,z] + sum_b (1 if dtime<=tgt else 0)*x[s,z,b]
        gt = gtime[(s, z)]
        ground_fast_coeff = 1.0 if gt <= tgt else 0.0
        drone_fast_sum = 0
        for b in B:
            if (s, z, b) in x:
                if dtime[(s, z, b)] <= tgt:
                    drone_fast_sum += x[(s, z, b)]
        # fast <= ground_fast_coeff * g + drone_fast_sum
        model.addCons(fast[(s, z)] <= ground_fast_coeff * g[(s, z)] + drone_fast_sum, name=f"fast_ub_{s}_{z}")

# Expected equity constraint
for grp in eq_target:
    grp_zones = [z for z in Z if zone_info[z]['equity_group'] == grp]
    total_grp_calls = sum(calls[(s, z)] for s in S for z in grp_zones)
    if total_grp_calls > 0:
        lhs = sum(calls[(s, z)] * fast[(s, z)] for s in S for z in grp_zones)
        model.addCons(lhs >= eq_min_fast[grp] * total_grp_calls, name=f"equity_{grp}")

# Tail equity constraint
for grp in eq_target:
    grp_zones = [z for z in Z if zone_info[z]['equity_group'] == grp]
    total_tail_calls = sum(calls[(s, z)] for s in tail_scens for z in grp_zones)
    if total_tail_calls > 0:
        lhs = sum(calls[(s, z)] * fast[(s, z)] for s in tail_scens for z in grp_zones)
        model.addCons(lhs >= eq_tail_min_fast[grp] * total_tail_calls, name=f"equity_tail_{grp}")

# 14. Priority assignment
# Priority 1: fast service
# Priority 2: non-fast drone or fast ground
# Priority 3: non-fast ground
for s in S:
    for z in Z:
        model.addCons(p1[(s, z)] + p2[(s, z)] + p3[(s, z)] == 1, name=f"pri_sum_{s}_{z}")
        # p1 <= fast[s,z]
        model.addCons(p1[(s, z)] <= fast[(s, z)], name=f"pri1_{s}_{z}")
        # p3 >= g[s,z] - fast[s,z] (if ground and not fast, must be p3)
        model.addCons(p3[(s, z)] >= g[(s, z)] - fast[(s, z)], name=f"pri3_{s}_{z}")

# ── Objective ──────────────────────────────────────────────────────────────
W = cfg['weights']

# Weekly cost (already in constraint, add to objective)
cost_obj = fixed_cost + drone_cost + kit_cost

# Expected response minutes: probability-weighted demand-weighted average
# resp[s,z] = sum_b dtime[s,z,b]*x[s,z,b] + gtime[s,z]*g[s,z]
# expected = sum_s p_s * sum_z calls[s,z] * resp[s,z] / sum_s p_s * sum_z calls[s,z]
# Linear: sum_s p_s * sum_z calls[s,z] * (sum_b dtime*x + gtime*g)
exp_resp = 0
for s in S:
    ps = float(scen_info[s]['probability'])
    for z in Z:
        c = calls[(s, z)]
        for b in B:
            if (s, z, b) in x:
                exp_resp += ps * c * dtime[(s, z, b)] * x[(s, z, b)]
        exp_resp += ps * c * gtime[(s, z)] * g[(s, z)]
# Divide by total probability-weighted calls
tot_prob_calls = sum(float(scen_info[s]['probability']) * tot_calls_s[s] for s in S)
exp_resp_avg = exp_resp / tot_prob_calls if tot_prob_calls > 0 else 0

# Tail response: average over tail scenarios (demand-weighted)
tail_resp = 0
for s in tail_scens:
    for z in Z:
        c = calls[(s, z)]
        for b in B:
            if (s, z, b) in x:
                tail_resp += c * dtime[(s, z, b)] * x[(s, z, b)]
        tail_resp += c * gtime[(s, z)] * g[(s, z)]
tail_total = sum(tot_calls_s[s] for s in tail_scens)
tail_resp_avg = tail_resp / tail_total if tail_total > 0 else 0

# Mortality risk: sum_s p_s * sum_z calls[s,z] * risk_z * exp(-decay * resp[s,z])
# Since resp[s,z] is a convex combination of fixed times selected by binaries,
# mortality = sum_s p_s * sum_z calls[s,z] * risk_z * sum_b exp(-decay*dtime[s,z,b])*x[s,z,b] + exp(-decay*gtime[s,z])*g[s,z]
# This is exactly linear!
decay = float(cfg['death_risk_decay_per_minute'])
mortality = 0
for s in S:
    ps = float(scen_info[s]['probability'])
    for z in Z:
        c = calls[(s, z)]
        risk = float(zone_info[z]['risk_weight'])
        for b in B:
            if (s, z, b) in x:
                mortality += ps * c * risk * math.exp(-decay * dtime[(s, z, b)]) * x[(s, z, b)]
        mortality += ps * c * risk * math.exp(-decay * gtime[(s, z)]) * g[(s, z)]

# Equity gap: sum_g max(0, min_fast_g - actual_fast_share_g)
# We already enforce min_fast as a constraint, so gap = 0. But to be safe, add penalty.
# Since constraints enforce it, equity gap = 0 in any feasible solution.
equity_gap = 0  # enforced by constraints

# Ground fallback: total ground share (probability-weighted)
ground_share = 0
for s in S:
    ps = float(scen_info[s]['probability'])
    for z in Z:
        ground_share += ps * calls[(s, z)] * g[(s, z)]
ground_share_avg = ground_share / tot_prob_calls if tot_prob_calls > 0 else 0

# Unserved: 0 since all zones must be served
unserved = 0

# Total objective
obj_expr = (W['weekly_cost'] * cost_obj
            + W['expected_response_minutes'] * exp_resp_avg
            + W['tail_response_minutes'] * tail_resp_avg
            + W['mortality_risk'] * mortality
            + W['equity_gap'] * equity_gap
            + W['ground_fallback'] * ground_share_avg
            + W['unserved_penalty'] * unserved)

model.setObjective(obj_expr, sense='minimize')

# ── Solve ──────────────────────────────────────────────────────────────────
print(f"Solving model: {len(B)} bases, {len(Z)} zones, {len(S)} scenarios")
print(f"Variables: {model.getNVars()}, Constraints: {model.getNCons()}")
print(f"Time limit: {time_limit}s")

try:
    model.optimize()
except Exception as e:
    print(f"Solver error: {e}")

status = model.getStatus()
print(f"Status: {status}")
print(f"Objective: {model.getObjVal():.8f}")
print(f"NSols: {model.getNSols()}")

# ── Extract solution ───────────────────────────────────────────────────────
sol = model.getBestSol()

open_bases = set()
drones_staged = {}
kits_staged = {}
for b in B:
    val = model.getVal(y[b])
    if val > 0.5:
        open_bases.add(b)
        drones_staged[b] = int(round(model.getVal(d[b])))
        kits_staged[b] = int(round(model.getVal(k[b])))
    else:
        drones_staged[b] = 0
        kits_staged[b] = 0

dispatches = {}
for s in S:
    for z in Z:
        mode = 'ground'
        primary = ''
        backup = ''
        priority = 3
        gv = model.getVal(g[(s, z)])
        if gv > 0.5:
            mode = 'ground'
            primary = ''
            backup = ''
            # Priority: 2 if ground time <= target, else 3
            grp = zone_info[z]['equity_group']
            tgt = eq_target[grp]
            priority = 2 if gtime[(s, z)] <= tgt else 3
        else:
            mode = 'drone'
            for b in B:
                if (s, z, b) in x and model.getVal(x[(s, z, b)]) > 0.5:
                    primary = b
                    break
            # Backup for high-priority
            if int(zone_info[z]['priority_zone']) == 1 and primary:
                for b2 in B:
                    if b2 != primary and (s, z, b2) in elig:
                        if (s, z, primary, b2) in bkp and model.getVal(bkp[(s, z, primary, b2)]) > 0.5:
                            backup = b2
                            break
            # Priority
            grp = zone_info[z]['equity_group']
            tgt = eq_target[grp]
            if primary and dtime.get((s, z, primary), 999) <= tgt:
                priority = 1
            else:
                priority = 2
        dispatches[(s, z)] = (mode, primary, backup, priority)

# ── Write solution.csv ─────────────────────────────────────────────────────
sol_path = f'{SUB}/solution.csv'
with open(sol_path, 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['row_type', 'scenario_id', 'zone_id', 'base_id', 'backup_base_id', 'drones', 'kits', 'mode', 'priority'])
    # Base rows
    for b in B:
        mode = 'open' if b in open_bases else 'closed'
        w.writerow(['base', '', '', b, '', drones_staged[b], kits_staged[b], mode, ''])
    # Dispatch rows
    for s in S:
        for z in Z:
            mode, primary, backup, priority = dispatches[(s, z)]
            if mode == 'ground':
                w.writerow(['dispatch', s, z, '', '', '', '', 'ground', str(priority)])
            else:
                w.writerow(['dispatch', s, z, primary, backup, '', '', 'drone', str(priority)])

print(f"Solution written to {sol_path}")

# ── Validation ─────────────────────────────────────────────────────────────
print("\n=== Validation ===")
errors = []

# Check all scenario-zone pairs have dispatch
for s in S:
    for z in Z:
        if (s, z) not in dispatches:
            errors.append(f"Missing dispatch for {s},{z}")

# Check drone rows reference open bases
for (s, z), (mode, primary, backup, pri) in dispatches.items():
    if mode == 'drone':
        if primary not in open_bases:
            errors.append(f"Drone base {primary} not open for {s},{z}")
        if not eligible(s, primary, z):
            errors.append(f"Base {primary} not eligible for {s},{z}")
        if int(zone_info[z]['priority_zone']) == 1:
            if not backup:
                errors.append(f"No backup for high-priority {s},{z}")
            elif backup == primary:
                errors.append(f"Backup same as primary for {s},{z}")
            elif backup not in open_bases:
                errors.append(f"Backup {backup} not open for {s},{z}")

# Check ground rows
for (s, z), (mode, primary, backup, pri) in dispatches.items():
    if mode == 'ground':
        if primary or backup:
            errors.append(f"Ground row has base fields for {s},{z}")

# Check budget
total_cost = sum(float(base_info[b]['fixed_cost']) for b in open_bases) \
           + float(cfg['drone_weekly_cost']) * sum(drones_staged.values()) \
           + float(cfg['kit_unit_cost']) * sum(kits_staged.values())
if total_cost > float(cfg['weekly_budget']) + 1:
    errors.append(f"Budget exceeded: {total_cost}")

# Check fleet
if sum(drones_staged.values()) > int(cfg['total_drones_available']):
    errors.append(f"Fleet exceeded: {sum(drones_staged.values())}")

# Check open base count
if not (int(cfg['min_open_bases']) <= len(open_bases) <= int(cfg['max_open_bases'])):
    errors.append(f"Open base count: {len(open_bases)}")

# Check staffing
for reg, (max_ob, max_dr) in staffing.items():
    reg_bases = [b for b in B if base_info[b]['region'] == reg]
    ob = sum(1 for b in reg_bases if b in open_bases)
    dr = sum(drones_staged[b] for b in reg_bases)
    if ob > max_ob:
        errors.append(f"Staffing open bases exceeded in {reg}: {ob} > {max_ob}")
    if dr > max_dr:
        errors.append(f"Staffing drones exceeded in {reg}: {dr} > {max_dr}")

# Check ground capacity
for s in S:
    for dd in regions:
        cap = ground_cap.get((s, dd), 0.0)
        load = sum(calls[(s, z)] for z in Z if zone_info[z]['district'] == dd and dispatches[(s, z)][0] == 'ground')
        if load > cap + 1e-6:
            errors.append(f"Ground capacity exceeded in {s},{dd}: {load} > {cap}")

# Check corridor capacity
for s in S:
    for o in regions:
        for dd in regions:
            cor = get_corridor(s, o, dd)
            if cor is None:
                continue
            cap = float(cor['max_calls_per_day'])
            load = 0
            for b in B:
                if base_info[b]['region'] != o:
                    continue
                for z in Z:
                    if zone_info[z]['district'] != dd:
                        continue
                    if dispatches[(s, z)][0] == 'drone' and dispatches[(s, z)][1] == b:
                        load += calls[(s, z)]
            if load > cap + 1e-6:
                errors.append(f"Corridor capacity exceeded in {s},{o}->{dd}: {load} > {cap}")

# Check kit coverage
for b in B:
    if b not in open_bases:
        continue
    for s in S:
        reserve = float(scen_info[s]['kit_reserve_factor'])
        load = sum(calls[(s, z)] for z in Z if dispatches[(s, z)][0] == 'drone' and dispatches[(s, z)][1] == b)
        if reserve * load > kits_staged[b] + 1e-6:
            errors.append(f"Kit coverage failed for {b} in {s}: need {reserve*load:.2f}, have {kits_staged[b]}")

# Check queue utilization
for s in S:
    for b in B:
        if b not in open_bases or drones_staged[b] == 0:
            continue
        load = sum(calls[(s, z)] for z in Z if dispatches[(s, z)][0] == 'drone' and dispatches[(s, z)][1] == b)
        util = load / (drones_staged[b] * cap_per_drone)
        if util > max_util + 1e-6:
            errors.append(f"Queue utilization exceeded for {b} in {s}: {util:.4f} > {max_util}")

# Check equity
for grp in eq_target:
    grp_zones = [z for z in Z if zone_info[z]['equity_group'] == grp]
    total_calls = sum(calls[(s, z)] for s in S for z in grp_zones)
    fast_calls = 0
    for s in S:
        for z in grp_zones:
            mode, primary, backup, pri = dispatches[(s, z)]
            tgt = eq_target[grp]
            if mode == 'drone' and dtime.get((s, z, primary), 999) <= tgt:
                fast_calls += calls[(s, z)]
            elif mode == 'ground' and gtime[(s, z)] <= tgt:
                fast_calls += calls[(s, z)]
    share = fast_calls / total_calls if total_calls > 0 else 0
    if share < eq_min_fast[grp] - 1e-6:
        errors.append(f"Equity gap for {grp}: {share:.4f} < {eq_min_fast[grp]}")

if errors:
    print(f"ERRORS ({len(errors)}):")
    for e in errors[:20]:
        print(f"  {e}")
else:
    print("All validation checks passed.")

model.free()
print("Done.")
